fn best_k(values: &[i32], k: usize) -> i32 {
    let mut sum: i32 = values[..k].iter().sum();
    let mut best = sum;
    for right in k..values.len() {
        sum += values[right] - values[right - k];
        best = best.max(sum);
    }
    best
}

